        add("elementalcraft.landing", "$(thing)ElementalCraft$() est un mod magique basé sur les 4 $(thing)éléments$() : $(thing)feu$(), $(thing)eau$(), $(thing)terre$() et $(thing)air$().$(br2)Vous pouvez également trouver plus d'informations sur le $(l:https://wiki.elementalcraft.org/)wiki$().");

        addPatchouliCategory("basics", "Bases", "Les bases et les mécaniques de début de jeu.");
        addPatchouliCategory("sources", "Sources", "$(ec:source)Sources$() sont des points naturels où les $(thing)éléments$() convergent.");
        addPatchouliCategory("element_production", "Production d'éléments", "$(thing)Élément$() peut être extrait des $(ec:source)sources$(), c'est le moyen le plus simple. Ou vous pouvez utiliser des synthétiseurs si vous ne trouvez pas de sources ou si elles ne sont pas disponibles.");
        addPatchouliCategory("instruments", "Instruments", "$(thing)Instruments$() sont les principaux outils de fabrication dans $(thing)ElementalCraft$().$(br)Ils consomment des $(thing)éléments$() et doivent être placés sur un $(ec:container)Conteneur$().");
        addPatchouliCategory("crafting", "Artisanat", "Voici tout ce que vous devez savoir sur l'$(thing)Artisanat$().");
        addPatchouliCategory("shrines", "Sanctuaires", "$(thing)Sanctuaires$() sont des outils puissants qui canalisent les $(thing)éléments$() dans le monde qui les entoure pour agir sur celui-ci.");
        addPatchouliCategory("shrine_upgrades", "Améliorations de sanctuaire", "Vous pouvez fabriquer des $(thing)améliorations de sanctuaire$() pour augmenter la puissance de vos $(thing)sanctuaires$(). Ces améliorations ne peuvent être placées qu'à des endroits spécifiques autour du $(thing)sanctuaire$().$(br)Les améliorations couvrent une large gamme de bonus allant de la $(thing)vitesse$(), $(thing)réduction de consommation$(), $(thing)portée$()... ou des bonus spécifiques comme $(thing)soie$() ou $(thing)fortune$() pour le $(l:shrines/oreshrine)sanctuaire de minerai$().");
        addPatchouliCategory("pipes", "Transfert d'éléments", "La capacité de déplacer des éléments à l'aide de tuyaux.");
        addPatchouliCategory("advanced", "Avancé", "Outils avancés et puissants de fin de jeu.");
        addPatchouliCategory("spells", "Sorts", "Les sorts vous permettent d'affecter directement le monde qui vous entoure.$(br)Vous pouvez toujours utiliser un sort, mais il se cassera si la ressource requise n'est pas présente. Pour les fournir, vous devez avoir un $(ec:holder)élément holder$() du même élément.");
        addPatchouliCategory("jewels", "Bijoux", "$(thing)Bijoux$() vous donnent des bonus passifs au coût d'éléments de votre $(ec:holder)élément holder$().$(br)Vous pouvez avoir cet effet en tenant le bijou dans une de vos mains ou en le plaçant sur un équipement à l'aide d'une enclume.");

